  'settings.privacy_desc': {
    en: 'All data stays on your device. Nothing is uploaded or shared.',
    es: 'Todos los datos permanecen en tu dispositivo. Nada se sube ni comparte.',
    'zh-CN': '所有数据留在您的设备上。不上传或分享任何内容。',
    'zh-TW': '所有資料留在您的裝置上。不上傳或分享任何內容。',
    vi: 'Tất cả dữ liệu ở trên thiết bị của bạn. Không tải lên hay chia sẻ gì.',
    tl: 'Lahat ng data ay nasa iyong device. Walang ini-upload o ibinabahagi.',
    hi: 'सभी डेटा आपके डिवाइस पर रहता है। कुछ भी अपलोड या साझा नहीं होता।',
    ko: '모든 데이터는 기기에 저장됩니다. 업로드되거나 공유되지 않습니다.',
    ar: 'تبقى جميع البيانات على جهازك. لا شيء يُرفع أو يُشارك.',
    fr: "Toutes les données restent sur votre appareil. Rien n'est partagé.",
    pt: 'Todos os dados ficam no seu dispositivo. Nada é enviado ou compartilhado.',
    ru: 'Все данные хранятся на вашем устройстве. Ничего не загружается.',
    ja: 'すべてのデータはデバイスに保存。アップロードや共有はされません。',
    am: 'ሁሉም ውሂብ በእርስዎ መሳሪያ ላይ ይቀራል። ምንም ነገር አይጫነም ወይም አይጋራም።',
    te: 'మొత్తం డేటా మీ పరికరంలోనే ఉంటుంది. ఏదీ అప్‌లోడ్ లేదా షేర్ చేయబడదు.',   pa: 'ਸਾਰਾ ਡਾਟਾ ਤੁਹਾਡੀ ਡਿਵਾਈਸ \'ਤੇ ਹੀ ਰਹਿੰਦਾ ਹੈ। ਕੁਝ ਵੀ ਅਪਲੋਡ ਜਾਂ ਸਾਂਝਾ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ।',   ta: 'அனைத்து தரவும் உங்கள் சாதனத்திலேயே இருக்கும். எதுவும் பதிவேற்றப்படாது அல்லது பகிரப்படாது.',   bn: 'সব ডেটা আপনার ডিভাইসেই থাকে। কিছুই আপলোড বা শেয়ার করা হয় না।',   id: 'Semua data tetap di perangkat Anda. Tidak ada yang diunggah atau dibagikan.',   ur: 'تمام ڈیٹا آپ کے آلے پر ہی رہتا ہے۔ کچھ بھی اپ لوڈ یا شیئر نہیں کیا جاتا۔',   tr: 'Tüm veriler cihazınızda kalır. Hiçbir şey yüklenmez veya paylaşılmaz.',
    sw: 'Data yote hubaki kwenye kifaa chako. Hakuna kinachopakiwa au kushirikiwa.',   it: 'Tutti i dati restano sul dispositivo. Nulla viene caricato o condiviso.',   th: 'ข้อมูลทั้งหมดอยู่ในอุปกรณ์ของคุณ ไม่มีการอัปโหลดหรือแชร์ข้อมูลใดๆ',   ms: 'Semua data kekal pada peranti anda. Tiada apa-apa dimuat naik atau dikongsi.',   ne: 'सबै डेटा तपाईंको उपकरणमै रहन्छ। केही पनि अपलोड वा साझा गरिँदैन।',   so: 'Dhammaan xogtu waxay ku sii jirtaa qalabkaaga. Waxba lama geliyo ama lama wadaago.',   ht: 'Tout done rete sou aparèy ou. Pa gen anyen yo telechaje oswa pataje.',
  },
