  'rights.general_info': {
    en: 'This is general educational information, not legal advice. Laws vary by state and situation.',
    es: 'Esta es información educativa general, no asesoría legal. Las leyes varían por estado.',
    'zh-CN': '这是一般教育信息，而非法律建议。法律因州而异。',
    'zh-TW': '這是一般教育資訊，而非法律建議。法律因州而異。',
    vi: 'Đây là thông tin giáo dục chung, không phải tư vấn pháp lý. Luật pháp thay đổi theo tiểu bang.',
    tl: 'Ito ay pangkalahatang impormasyon, hindi legal na payo. Nagbabago ang batas bawat estado.',
    hi: 'यह सामान्य शैक्षिक जानकारी है, कानूनी सलाह नहीं। कानून राज्य के अनुसार अलग होते हैं।',
    ko: '이것은 일반적인 교육 정보이며 법률 자문이 아닙니다. 법률은 주마다 다릅니다.',
    ar: 'هذه معلومات تعليمية عامة، وليست مشورة قانونية. تختلف القوانين حسب الولاية.',
    fr: "Ceci est une information éducative générale, pas un conseil juridique. Les lois varient selon l'État.",
    pt: 'Esta é uma informação educacional geral, não aconselhamento jurídico. As leis variam por estado.',
    ru: 'Это общая образовательная информация, а не юридическая консультация. Законы различаются.',
    ja: 'これは一般的な教育情報であり、法律上のアドバイスではありません。法律は州によって異なります。',
    am: 'ይህ አጠቃላይ ትምህርታዊ መረጃ ነው፣ የህግ ምክር አይደለም። ህጎች በግዛት ይለያያሉ።',
    te: 'ఇది సాధారణ విద్యా సమాచారం, న్యాయ సలహా కాదు. చట్టాలు రాష్ట్రం మరియు పరిస్థితిని బట్టి మారుతాయి.',   pa: 'ਇਹ ਆਮ ਸਿੱਖਿਆਤਮਕ ਜਾਣਕਾਰੀ ਹੈ, ਕਾਨੂੰਨੀ ਸਲਾਹ ਨਹੀਂ। ਕਾਨੂੰਨ ਰਾਜ ਅਤੇ ਸਥਿਤੀ ਅਨੁਸਾਰ ਵੱਖਰੇ ਹੁੰਦੇ ਹਨ।',   ta: 'இது பொதுவான கல்வித் தகவல்; சட்ட ஆலோசனை அல்ல. சட்டங்கள் மாநிலம் மற்றும் சூழ்நிலையைப் பொறுத்து மாறுபடும்.',   bn: 'এটি সাধারণ শিক্ষামূলক তথ্য, আইনি পরামর্শ নয়। রাজ্য ও পরিস্থিতি অনুযায়ী আইন ভিন্ন হয়।',   id: 'Ini adalah informasi edukasi umum, bukan nasihat hukum. Hukum berbeda menurut negara bagian dan situasi.',   ur: 'یہ عام تعلیمی معلومات ہیں، قانونی مشورہ نہیں۔ قوانین ریاست اور صورتِ حال کے لحاظ سے مختلف ہوتے ہیں۔',   tr: 'Bu genel eğitim amaçlı bilgidir, hukuki danışmanlık değildir. Yasalar eyalete ve duruma göre değişir.',
    sw: 'Haya ni maelezo ya jumla ya kielimu, si ushauri wa kisheria. Sheria hutofautiana kulingana na jimbo na hali.',   it: 'Queste sono informazioni educative generali, non consulenza legale. Le leggi variano in base allo Stato e alla situazione.',   th: 'นี่คือข้อมูลการศึกษาทั่วไป ไม่ใช่คำแนะนำทางกฎหมาย กฎหมายแตกต่างกันไปตามรัฐและสถานการณ์',   ms: 'Ini ialah maklumat pendidikan umum, bukan nasihat undang-undang. Undang-undang berbeza mengikut negeri dan situasi.',   ne: 'यो सामान्य शैक्षिक जानकारी हो, कानुनी सल्लाह होइन। राज्य र परिस्थितिअनुसार कानुन फरक हुन्छन्।',   so: 'Tani waa macluumaad waxbarasho oo guud, ma aha talo sharci. Sharciyadu way ku kala duwan yihiin gobol iyo xaalad.',   ht: 'Sa a se enfòmasyon edikatif jeneral, se pa konsèy legal. Lwa yo varye selon eta ak sitiyasyon an.',
  },
