  'resources.perm_denied': {
    en: 'Location access was denied. You can enter a city or ZIP code below instead.',
    es: 'Acceso de ubicación denegado. Ingresa una ciudad o código postal.',
    'zh-CN': '位置访问被拒绝。请在下方输入城市或邮编。',
    'zh-TW': '位置存取被拒絕。請在下方輸入城市或郵遞區號。',
    vi: 'Quyền truy cập vị trí bị từ chối. Nhập thành phố hoặc ZIP bên dưới.',
    tl: 'Tinanggihan ang access sa lokasyon. Mag-enter ng city o ZIP code.',
    hi: 'स्थान पहुँच अस्वीकार। नीचे शहर या ZIP कोड दर्ज करें।',
    ko: '위치 접근이 거부되었습니다. 아래에 도시나 ZIP 코드를 입력하세요.',
    ar: 'تم رفض الوصول إلى الموقع. أدخل مدينة أو رمزًا بريديًا.',
    fr: "Accès à la localisation refusé. Entrez une ville ou un code postal.",
    pt: 'Acesso à localização negado. Digite uma cidade ou CEP abaixo.',
    ru: 'Доступ к местоположению запрещён. Введите город или почтовый индекс.',
    ja: '位置情報へのアクセスが拒否されました。都市またはZIPを入力してください。',
    am: 'ቦታ ተደራሽነት ተከልክሏል። ከዚህ በታች ከተማ ወይም ZIP ያስገቡ።',
    te: 'స్థాన ప్రాప్యత తిరస్కరించబడింది. బదులుగా క్రింద నగరం లేదా ZIP కోడ్ నమోదు చేయవచ్చు.',   pa: 'ਟਿਕਾਣੇ ਦੀ ਪਹੁੰਚ ਰੱਦ ਕਰ ਦਿੱਤੀ ਗਈ। ਇਸ ਦੀ ਬਜਾਏ ਤੁਸੀਂ ਹੇਠਾਂ ਸ਼ਹਿਰ ਜਾਂ ZIP ਕੋਡ ਦਰਜ ਕਰ ਸਕਦੇ ਹੋ।',   ta: 'இருப்பிட அணுகல் மறுக்கப்பட்டது. அதற்குப் பதிலாக கீழே நகரம் அல்லது ZIP குறியீட்டை உள்ளிடலாம்.',   bn: 'অবস্থান ব্যবহারের অনুমতি প্রত্যাখ্যান করা হয়েছে। এর বদলে নিচে একটি শহর বা ZIP কোড লিখতে পারেন।',   id: 'Akses lokasi ditolak. Anda dapat memasukkan kota atau kode ZIP di bawah sebagai gantinya.',   ur: 'مقام تک رسائی مسترد کر دی گئی۔ اس کے بجائے آپ نیچے شہر یا ZIP کوڈ درج کر سکتے ہیں۔',   tr: 'Konum erişimi reddedildi. Bunun yerine aşağıya bir şehir veya ZIP kodu girebilirsiniz.',
    sw: 'Ruhusa la eneo limekataliwa. Unaweza kuingiza jiji au msimbo wa ZIP hapa chini badala yake.',   it: 'L\'accesso alla posizione è stato negato. Puoi inserire invece una città o un CAP qui sotto.',   th: 'การเข้าถึงตำแหน่งถูกปฏิเสธ คุณสามารถป้อนชื่อเมืองหรือรหัสไปรษณีย์ด้านล่างแทนได้',   ms: 'Akses lokasi ditolak. Sebaliknya, anda boleh memasukkan bandar atau kod ZIP di bawah.',   ne: 'स्थान पहुँच अस्वीकार गरियो। यसको सट्टा तल सहर वा ZIP कोड प्रविष्ट गर्न सक्नुहुन्छ।',   so: 'Gelitaanka goobta waa la diiday. Bedelkeeda, waxaad hoos ku qori kartaa magaalo ama ZIP code.',   ht: 'Yo refize aksè ak kote a. Ou ka antre yon vil oswa yon kòd ZIP anba a pito.',
  },
