    tl: 'Hindi makuha ang lokasyon. Subukang mag-enter ng city o ZIP.',
    hi: 'स्थान नहीं मिला। कृपया शहर या ZIP कोड दर्ज करें।',
    ko: '위치를 가져올 수 없습니다. 도시나 ZIP 코드를 입력해 보세요.',
