  'log.empty_desc': {
    en: 'Document police interactions to protect yourself and your community. All records stay on your device.',
    es: 'Documenta interacciones policiales para protegerte. Los registros permanecen en tu dispositivo.',
    'zh-CN': '记录与警察的互动以保护自己和社区。所有记录保留在您的设备上。',
    'zh-TW': '記錄與警察的互動以保護自己和社群。所有記錄保留在您的裝置上。',
    vi: 'Ghi lại tương tác với cảnh sát để bảo vệ bạn. Tất cả hồ sơ ở trên thiết bị.',
    tl: 'Idokumento ang pakikipag-ugnayan sa pulis. Ang lahat ng rekord ay nasa device mo.',
    hi: 'खुद को बचाने के लिए पुलिस से बातचीत दर्ज करें। सभी रिकॉर्ड आपके डिवाइस पर रहते हैं।',
    ko: '자신을 보호하기 위해 경찰 상호작용을 기록하세요. 모든 기록은 기기에 남습니다.',
    ar: 'وثّق التفاعلات مع الشرطة لحماية نفسك. جميع السجلات تبقى على جهازك.',
    fr: 'Documentez les interactions avec la police. Tous les dossiers restent sur votre appareil.',
    pt: 'Documente interações com a polícia. Todos os registros ficam no seu dispositivo.',
    ru: 'Документируйте взаимодействие с полицией. Все записи хранятся на устройстве.',
    ja: '警察との交流を記録して自分を守りましょう。記録はすべてデバイスに保存されます。',
    am: 'ራስዎን ለመጠበቅ ከፖሊስ ጋር ያለውን ግንኙነት ይመዝግቡ። ሁሉም መዛግብት በእርስዎ መሳሪያ ላይ ይቆያሉ።',
    te: 'మిమ్మల్ని మరియు మీ సమాజాన్ని రక్షించుకోవడానికి పోలీసులతో జరిగిన పరస్పర చర్యలను నమోదు చేయండి. అన్ని రికార్డులు మీ పరికరంలోనే ఉంటాయి.',   pa: 'ਆਪਣੇ ਅਤੇ ਆਪਣੇ ਭਾਈਚਾਰੇ ਦੀ ਰੱਖਿਆ ਲਈ ਪੁਲਿਸ ਨਾਲ ਹੋਈਆਂ ਗੱਲਬਾਤਾਂ ਦਾ ਦਸਤਾਵੇਜ਼ ਬਣਾਓ। ਸਾਰੇ ਰਿਕਾਰਡ ਤੁਹਾਡੀ ਡਿਵਾਈਸ \'ਤੇ ਹੀ ਰਹਿੰਦੇ ਹਨ।',   ta: 'உங்களையும் உங்கள் சமூகத்தையும் பாதுகாக்க காவல்துறையுடனான தொடர்புகளைப் பதிவு செய்யுங்கள். அனைத்து பதிவுகளும் உங்கள் சாதனத்திலேயே இருக்கும்.',   bn: 'নিজেকে ও আপনার সম্প্রদায়কে সুরক্ষিত রাখতে পুলিশের সঙ্গে মিথস্ক্রিয়াগুলো নথিবদ্ধ করুন। সব রেকর্ড আপনার ডিভাইসেই থাকে।',   id: 'Dokumentasikan interaksi dengan polisi untuk melindungi diri dan komunitas Anda. Semua catatan tetap di perangkat Anda.',   ur: 'اپنے اور اپنی برادری کے تحفظ کے لیے پولیس کے ساتھ ہونے والی بات چیت کا ریکارڈ رکھیں۔ تمام ریکارڈ آپ کی ڈیوائس پر ہی رہتے ہیں۔',   tr: 'Kendinizi ve topluluğunuzu korumak için polisle etkileşimlerinizi belgeleyin. Tüm kayıtlar cihazınızda kalır.',
    sw: 'Andika maingiliano yako na polisi ili kujilinda na kulinda jamii yako. Rekodi zote hubaki kwenye kifaa chako.',   it: 'Documenta le interazioni con la polizia per proteggere te stesso e la tua comunità. Tutti i record restano sul tuo dispositivo.',   th: 'บันทึกการติดต่อกับตำรวจเพื่อปกป้องตนเองและชุมชนของคุณ บันทึกทั้งหมดจะอยู่ในอุปกรณ์ของคุณ',   ms: 'Dokumentasikan interaksi dengan polis untuk melindungi diri dan komuniti anda. Semua rekod kekal pada peranti anda.',   ne: 'आफू र आफ्नो समुदायलाई सुरक्षित राख्न प्रहरीसँगका अन्तरक्रियाहरू अभिलेख गर्नुहोस्। सबै रेकर्ड तपाईंको उपकरणमै रहन्छन्।',   so: 'Diiwaangeli isdhexgalka booliiska si aad naftaada iyo bulshadaada u ilaaliso. Dhammaan diiwaannadu qalabkaaga ayay ku jiraan.',   ht: 'Dokimante entèraksyon ak lapolis pou pwoteje tèt ou ak kominote w la. Tout dosye yo rete sou aparèy ou.',
  },
