    'zh-CN': '请添加遭遇描述。',                          'zh-TW': '請新增遭遇描述。',
    vi: 'Vui lòng thêm mô tả về cuộc gặp gỡ.',        tl: 'Mangyaring magdagdag ng paglalarawan ng pakikipagtagpo.',
    hi: 'कृपया मुठभेड़ का विवरण जोड़ें।',               ko: '조우에 대한 설명을 추가해 주세요.',
