    sw: 'Bado hakuna machapisho katika kategoria hii.\\nKuwa wa kwanza kushiriki!',   it: 'Non ci sono ancora post in questa categoria.\\nSii il primo a condividere!',   th: 'ยังไม่มีโพสต์ในหมวดหมู่นี้\\nมาเป็นคนแรกที่แบ่งปันกันเถอะ!',   ms: 'Belum ada siaran dalam kategori ini.\\nJadilah orang pertama untuk berkongsi!',   ne: 'यस श्रेणीमा अहिलेसम्म कुनै पोस्ट छैन।\\nसाझा गर्ने पहिलो व्यक्ति बन्नुहोस्!',   so: 'Weli wax qoraallo ah kuma jiraan qaybtan.\\nNoqo qofka ugu horreeya ee wax wadaaga!',   ht: 'Poko gen pòs nan kategori sa a.\\nSe pou w premye moun ki pataje!',
