    pa: 'ਰਿਕਾਰਡਿੰਗ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਅਧਿਕਾਰੀ ਨੂੰ ਇਹ ਚਲਾਓ।',
