  'translate.voice_eas_msg': {
    en: 'Voice input requires a full app build (EAS Build), not Expo Go.\n\nType what the officer said instead.',
    es: 'La entrada de voz requiere una compilación completa (EAS Build), no Expo Go.\n\nEscribe lo que dijo el oficial en su lugar.',
    'zh-CN': '语音输入需要完整应用构建（EAS Build），而不是Expo Go。\n\n请改为输入警察所说的话。',
    'zh-TW': '語音輸入需要完整應用構建（EAS Build），而不是Expo Go。\n\n請改為輸入警察所說的話。',
    vi: 'Đầu vào giọng nói cần bản dựng ứng dụng đầy đủ (EAS Build), không phải Expo Go.\n\nThay vào đó hãy nhập những gì cảnh sát nói.',
    hi: 'वॉइस इनपुट के लिए पूर्ण ऐप बिल्ड (EAS Build) आवश्यक है, Expo Go नहीं।\n\nइसके बजाय अधिकारी ने जो कहा वह टाइप करें।',
    ko: '음성 입력은 전체 앱 빌드(EAS Build)가 필요하며 Expo Go는 불가합니다.\n\n대신 경찰이 말한 내용을 입력하세요.',
    ar: 'إدخال الصوت يتطلب إنشاء تطبيق كامل (EAS Build)، وليس Expo Go.\n\naكتب ما قاله الضابط بدلاً من ذلك.',
    fr: 'La saisie vocale nécessite une compilation complète (EAS Build), pas Expo Go.\n\nTapez ce qu\'a dit l\'agent à la place.',
    pt: 'A entrada de voz requer uma compilação completa (EAS Build), não o Expo Go.\n\nDigite o que o oficial disse.',
    ru: 'Голосовой ввод требует полной сборки (EAS Build), а не Expo Go.\n\nВведите слова офицера вместо этого.',
    ja: '音声入力には完全なアプリビルド（EAS Build）が必要です。Expo Goは使用できません。\n\n代わりに警官の言葉を入力してください。',
    te: 'శబ్దం ఇన్‌పుట్ పూర్తి యాప్ నిర్మాణాన్ని అవసరం చేస్తుంది (EAS నిర్మాణం), ఎక్స్‌పో గో కాదు.\n\nఅది చెప్పినది బదులుగా టైప్ చేయండి.',
    pa: 'ਆਵਾਜ਼ ਇਨਪੁਟ ਲਈ ਪੂਰੀ ਐਪ ਬਣਾਉਣ ਦੀ ਲੋੜ ਹੈ (EAS ਬਣਾਉਣ), ਐਕਸਪੋ ਗੋ ਨਹੀਂ।\n\nਜੋ ਅਧਿਕਾਰੀ ਨੇ ਕਿਹਾ ਉਸਦਾ ਬਦਲਾ ਲਿਖੋ।',
    ta: 'குரல் உள்ளீடு முழு செயலி கட்டமைப்பை தேவைப்படுகிறது (EAS கட்டமைப்பு), எக்ஸ்போ கோ இல்லை.\n\nஅதாவது அதிகாரி கூறியதை பதிலாக எழுதவும்.',
    bn: 'ভয়েস ইনপুটের জন্য একটি পূর্ণ অ্যাপ নির্মাণের প্রয়োজন (EAS নির্মাণ), এক্সপো গো নয়।\n\nঅফিসার যা বলেছে তা পরিবর্তে টাইপ করুন।',
    id: 'Input suara memerlukan pembangunan aplikasi penuh (EAS Build), bukan Expo Go.\n\nKetik apa yang dikatakan petugas sebagai gantinya.',
    ur: 'آواز کی ان پٹ کے لیے مکمل ایپ کی تعمیر کی ضرورت ہوتی ہے (EAS تعمیر)، ایکسپو گو نہیں۔\n\nجو کچھ افسر نے کہا اس کا جواب ٹائپ کریں۔',
    tr: 'Ses girişi tam bir uygulama inşası gerektirir (EAS İnşası), Expo Go değil.\n\nMemurun söylediklerini bunun yerine yazın.',
    sw: 'Kuingiza sauti kunahitaji ujenzi kamili wa programu (EAS Build), sio Expo Go.\n\nAndika kile afisa alisema badala yake.',
    it: 'L\'input vocale richiede una build completa dell\'app (EAS Build), non Expo Go.\n\nDigita ciò che ha detto l\'ufficiale invece.',
    th: 'การป้อนเสียงต้องการการสร้างแอปเต็มรูปแบบ (EAS Build) ไม่ใช่ Expo Go.\n\nพิมพ์สิ่งที่เจ้าหน้าที่พูดแทน.',
    ms: 'Input suara memerlukan binaan aplikasi penuh (EAS Build), bukan Expo Go.\n\nKetik apa yang dikatakan pegawai sebagai ganti.',
    ne: 'आवाज इनपुटको लागि पूर्ण एप निर्माणको आवश्यकता पर्छ (EAS निर्माण), एक्स्पो गो होइन।\n\nअधिकारीले भनेको कुरा यसको सट्टा टाइप गर्नुहोस्।',
    so: 'Gelinta codka waxay u baahan tahay dhismaha buuxa ee barnaamijka (EAS Build), ma aha Expo Go.\n\nQor waxa sarkaalka uu sheegay bedelkeeda.',
    ht: 'Antre vwa a mande yon konstriksyon aplikasyon konplè (EAS Konstriksyon), pa Expo Go.\n\nTape sa ofisye a te di olye.',
    tl: 'Ang input ng boses ay nangangailangan ng isang buong build ng app (EAS Build), hindi Expo Go.',
    am: 'የድምፅ ግቤት ሙሉ የአፕ ማስተካከል (EAS ማስተካከል) ይፈልጋል፣ እንደ እንቅስቃሴ አይደለም።',
  },

