    hi: 'कृपया कानूनी टेक्स्ट पेस्ट करें, नमूना लोड करें, या दस्तावेज़ की तस्वीर स्कैन करें।',
    ko: '법적 텍스트를 붙여넣거나 샘플을 불러오거나 문서 이미지를 스캔하세요.',
