    am: 'ሕጋዊ ጽሑፍ ይለጥፉ፣ ናሙና ያምጡ ወይም ሰነዱን ያሰሱ።',
    te: 'దయచేసి చట్టపరమైన పాఠ్యాన్ని పేస్ట్ చేయండి, ఒక నమూనాను లోడ్ చేయండి లేదా ఒక డాక్యుమెంట్ ఇమేజ్‌ను స్కాన్ చేయండి.',
