    bn: 'ছবিটি থেকে টেক্সট পড়তে পারিনি। দয়া করে আবার চেষ্টা করুন অথবা টেক্সটটি ম্যানুয়ালি পেস্ট করুন।',
    id: 'Tidak dapat membaca teks dari gambar. Silakan coba lagi atau tempel teks secara manual.',
    ur: 'تصویر سے متن پڑھنے میں ناکام رہے۔ براہ کرم دوبارہ کوشش کریں یا متن کو دستی طور پر پیسٹ کریں۔',
    tr: 'Görüntüden metin okunamadı. Lütfen tekrar deneyin veya metni manuel olarak yapıştırın.',
    sw: 'Hakuweza kusoma maandiko kutoka kwa picha. Tafadhali jaribu tena au bandika maandiko kwa mikono.',
