    bn: 'শেয়ার করার জন্য নির্ধারিত সময়সীমা স্ক্যান করুন',
    id: 'Pindai untuk membagikan tenggat waktu yang diekstrak',
    ur: 'نکالی گئی آخری تاریخیں شیئر کرنے کے لیے اسکین کریں',
    tr: 'Çıkarılan son tarihleri paylaşmak için tarayın',
    sw: 'Piga picha ili kushiriki tarehe zilizopatikana',
    it: 'Scansiona per condividere le scadenze estratte',
    th: 'สแกนเพื่อแชร์กำหนดเวลาที่ดึงออกมา',
    ms: 'Imbas untuk berkongsi tarikh akhir yang diekstrak',
    ne: 'निकालीएका म्यादहरू साझा गर्न स्क्यान गर्नुहोस्',
    so: 'Scan si aad ula wadaagto taariikhaha la soo saaray',
