    pt: '📱 Compartilhamento de Código QR', ru: '📱 Обмен QR-кодом',
    ja: '📱 QRコード共有', am: '📱 QR ኮድ ማጋራት',
    te: '📱 QR కోడ్ పంచుకోవడం',
    pa: '📱 QR ਕੋਡ ਸਾਂਝਾ ਕਰਨਾ',
    ta: '📱 QR குறியீடு பகிர்வு',
    bn: '📱 QR কোড শেয়ারিং',
    id: '📱 Berbagi Kode QR',
    ur: '📱 QR کوڈ شیئرنگ',
    tr: '📱 QR Kod Paylaşımı',
    sw: '📱 Kushiriki Kodi ya QR',
    it: '📱 Condivisione del Codice QR',
    th: '📱 การแชร์ QR โค้ด',
    ms: '📱 Berkongsi Kod QR',
    ne: '📱 QR कोड साझेदारी',
