  'docs.guide_qr_body': {
    en: 'After extracting, tap the grid icon (⊞) to generate a QR code. Share it with a lawyer or advocate so they can instantly see your key deadlines.',
    es: 'Después de extraer, toca el icono de cuadrícula (⊞) para generar un código QR. Compártelo con un abogado o defensor para que puedan ver tus plazos clave al instante.',
    'zh-CN': '提取后，点击网格图标(⊞)生成二维码。与律师或倡导者分享，让他们立即看到您的关键截止日期。',
    'zh-TW': '提取後，點擊網格圖標(⊞)生成二維碼。與律師或倡導者分享，讓他們立即看到您的關鍵截止日期。',
    vi: 'Sau khi trích xuất, nhấn biểu tượng lưới (⊞) để tạo mã QR. Chia sẻ với luật sư hoặc người bào chữa để họ có thể thấy ngay các thời hạn chính của bạn.',
    hi: 'निकालने के बाद, QR कोड बनाने के लिए ग्रिड आइकन (⊞) टैप करें। किसी वकील या वकालत करने वाले के साथ साझा करें ताकि वे आपकी प्रमुख समयसीमाएं तुरंत देख सकें।',
    fr: 'Après l\'extraction, appuyez sur l\'icône grille (⊞) pour générer un code QR. Partagez-le avec un avocat pour qu\'il puisse voir immédiatement vos échéances clés.',
    te: 'ఎక్స్‌ట్రాక్ట్ చేసిన తర్వాత, QR కోడ్‌ను రూపొందించడానికి గ్రిడ్ చిహ్నం (⊞) పై ట్యాప్ చేయండి. మీ కీలక గడువులను వెంటనే చూడటానికి ఒక న్యాయవాది లేదా న్యాయవాదితో పంచుకోండి.',
    pa: 'ਕੱਢਣ ਤੋਂ ਬਾਅਦ, QR ਕੋਡ ਬਣਾਉਣ ਲਈ ਗ੍ਰਿਡ ਆਈਕਨ (⊞) \'ਤੇ ਟੈਪ ਕਰੋ। ਇਸਨੂੰ ਇੱਕ ਵਕੀਲ ਜਾਂ ਵਕੀਲ ਨਾਲ ਸਾਂਝਾ ਕਰੋ ਤਾਂ ਜੋ ਉਹ ਤੁਹਾਡੇ ਮੁੱਖ ਡੈਡਲਾਈਨ ਨੂੰ ਤੁਰੰਤ ਦੇਖ ਸਕਣ।',
    ta: 'எடுக்கப்பட்ட பிறகு, QR குறியீட்டை உருவாக்க கிரிட் ஐகானில் (⊞) தட்டவும். உங்கள் முக்கிய காலக்கெடுவுகளை உடனடியாகப் பார்க்க ஒரு வழக்கறிஞர் அல்லது வழக்குரைஞருடன் பகிரவும்.',
    bn: 'এক্সট্রাক্ট করার পর, QR কোড তৈরি করতে গ্রিড আইকনে (⊞) ট্যাপ করুন। এটি একটি আইনজীবী বা অ্যাডভোকেটের সাথে শেয়ার করুন যাতে তারা আপনার মূল সময়সীমাগুলি তাত্ক্ষণিকভাবে দেখতে পারে।',
    id: 'Setelah mengekstrak, ketuk ikon grid (⊞) untuk menghasilkan kode QR. Bagikan dengan pengacara atau advokat agar mereka dapat segera melihat tenggat waktu penting Anda.',
    ur: 'نکالنے کے بعد، QR کوڈ بنانے کے لیے گرڈ آئیکن (⊞) پر ٹیپ کریں۔ اسے ایک وکیل یا وکیل کے ساتھ شیئر کریں تاکہ وہ آپ کی اہم ڈیڈ لائنز کو فوری طور پر دیکھ سکیں۔',
    tr: 'Çıkardıktan sonra, bir QR kodu oluşturmak için ızgara simgesine (⊞) dokunun. Anahtar son tarihlerinizin anında görünmesi için bir avukat veya savunma avukatıyla paylaşın.',
    sw: 'Baada ya kutoa, gusa ikoni ya gridi (⊞) ili kuunda kodi ya QR. Shiriki nayo na wakili au wakili ili waweze kuona tarehe zako muhimu mara moja.',
    it: 'Dopo aver estratto, tocca l\'icona della griglia (⊞) per generare un codice QR. Condividilo con un avvocato o un legale in modo che possa vedere immediatamente le tue scadenze chiave.',
    th: 'หลังจากดึงข้อมูลแล้ว ให้แตะที่ไอคอนกริด (⊞) เพื่อสร้าง QR โค้ด แบ่งปันกับทนายความหรือทนายความเพื่อให้พวกเขาสามารถดูเส้นตายที่สำคัญของคุณได้ทันที',
    ms: 'Selepas mengekstrak, ketuk ikon grid (⊞) untuk menghasilkan kod QR. Kongsikan dengan peguam atau peguam bela supaya mereka dapat melihat tarikh akhir penting anda dengan segera.',
    ne: 'निकालिसकेपछि, QR कोड उत्पन्न गर्न ग्रिड आइकन (⊞) मा ट्याप गर्नुहोस्। यो एक वकिल वा अधिवक्तासँग साझा गर्नुहोस् ताकि उनीहरूले तुरुन्तै तपाईंका प्रमुख समयसीमाहरू देख्न सकून्।',
    so: 'Ka dib markii la soo saaro, taabo astaanta shabakad (⊞) si aad u abuurto koodh QR. La wadaag qareen ama qareen si ay si degdeg ah u arki karaan waqtigaaga muhiimka ah.',
    ht: 'Apre ekstraksyon, tape sou ikon griy la (⊞) pou jenere yon kòd QR. Pataje li ak yon avoka oswa avoka pou yo ka wè dat limit kle ou yo imedyatman.',
    tl: 'Pagkatapos ng pagkuha, i-tap ang icon ng grid (⊞) upang bumuo ng isang QR code. Ibahagi ito sa isang abogado o tagapagtaguyod upang agad nilang makita ang iyong mga pangunahing deadline.',
    ko: '추출 후 그리드 아이콘 (⊞)을 탭하여 QR 코드를 생성하세요. 변호사나 옹호자와 공유하여 그들이 귀하의 주요 마감일을 즉시 볼 수 있도록 하세요.',
    ar: 'بعد الاستخراج، انقر على أيقونة الشبكة (⊞) لإنشاء رمز QR. شاركه مع محامٍ أو مدافع حتى يتمكنوا من رؤية المواعيد النهائية الرئيسية الخاصة بك على الفور.',
    pt: 'Após a extração, toque no ícone de grade (⊞) para gerar um código QR. Compartilhe-o com um advogado ou defensor para que eles possam ver instantaneamente seus prazos principais.',
    ru: 'После извлечения нажмите на значок сетки (⊞), чтобы сгенерировать QR-код. Поделитесь им с адвокатом или защитником, чтобы они могли мгновенно увидеть ваши ключевые сроки.',
    ja: '抽出後、グリッドアイコン（⊞）をタップしてQRコードを生成します。弁護士や支援者と共有して、彼らがあなたの重要な締切を即座に確認できるようにします。',
    am: '"ወቅታዊ ወቅቶችን ወደ ዳሽቦርድ ይደብቁ" ይጫኑ እና ዋነኛ ወቅቶችዎ በዋነኛ የይዘት ማዕከል በላይ ይታይ ይሆናል።',
  },
