    pt: 'Você deve mostrar sua licença, registro e comprovante de seguro.',
    ru: 'Вы должны показать свою лицензию, регистрацию и доказательство страховки.',
    ja: '運転免許証、登録証、保険証明書を提示する必要があります。',
    am: 'የእርስዎን ፈቃድ፣ መዝግብ እና የመድኃኒት ማስረጃ መግለጽ አለብዎት።',
    te: 'మీ లైసెన్స్, నమోదు మరియు బీమా సాక్ష్యం చూపించాలి.',
    pa: 'ਤੁਹਾਨੂੰ ਆਪਣੀ ਲਾਇਸੈਂਸ, ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਅਤੇ ਬੀਮਾ ਦਾ ਸਬੂਤ ਦਿਖਾਉਣਾ ਚਾਹੀਦਾ ਹੈ।',
    ta: 'உங்கள் உரிமம், பதிவு மற்றும் காப்பீட்டு சான்று காட்ட வேண்டும்.',
    bn: 'আপনাকে আপনার লাইসেন্স, নিবন্ধন এবং বীমার প্রমাণ দেখাতে হবে।',
    id: 'Anda harus menunjukkan lisensi, pendaftaran, dan bukti asuransi Anda.',
    ur: 'آپ کو اپنی لائسنس، رجسٹریشن، اور انشورنس کا ثبوت دکھانا ہوگا۔',
    tr: 'Lisansınızı, kaydınızı ve sigorta belgenizi göstermek zorundasınız.',
    sw: 'Lazima uonyeshe leseni yako, usajili, na uthibitisho wa bima.',
    it: 'Devi mostrare la tua patente, registrazione e prova di assicurazione.',
    th: 'คุณต้องแสดงใบอนุญาต ข้อมูลการลงทะเบียน และหลักฐานการประกันภัยของคุณ',
    ms: 'Anda mesti menunjukkan lesen, pendaftaran, dan bukti insurans anda.',
    ne: 'तपाईंले आफ्नो लाइसेन्स, दर्ता र बीमा प्रमाण देखाउनु पर्छ।',
    so: 'Waa inaad muujisaa liisankaaga, diiwaangelinta, iyo caddeynta caymiska.',
    ht: 'Ou dwe montre lisans ou, enskripsyon, ak prèv asirans.',
