    ta: 'வாதிடாதீர்கள் அல்லது எதிர்ப்பு தெரிவிக்காதீர்கள் - அதனை நீதிமன்றத்தில் சவால் செய்யுங்கள்.',
    bn: 'বিবাদ করবেন না বা প্রতিরোধ করবেন না - বরং আদালতে এটি চ্যালেঞ্জ করুন।',
    id: 'Jangan berdebat atau melawan - tantang itu di pengadilan sebagai gantinya.',
    ur: 'بحث نہ کریں یا مزاحمت نہ کریں - اس کو عدالت میں چیلنج کریں۔',
    tr: 'Tartışmayın veya direnmeyin - bunun yerine mahkemede itiraz edin.',
    sw: 'Usijadili au kupinga - badala yake, pingana na hilo mahakamani.',
    it: 'Non discutere o resistere - contestalo in tribunale invece.',
