    ms: 'Jangan berdebat atau melawan - cabar itu di mahkamah sebaliknya.',
    ne: 'विवाद नगर्नुहोस् वा प्रतिरोध नगर्नुहोस् - यसको सट्टा अदालतमा चुनौती दिनुहोस्।',
