    sw: 'Una haki ya kujua kwa nini unakamatwa.',
    it: 'Hai il diritto di sapere perché sei stato arrestato.',
    th: 'คุณมีสิทธิ์ที่จะรู้ว่าทำไมคุณถึงถูกจับกุม',
    ms: 'Anda berhak untuk mengetahui mengapa anda ditangkap.',
    ne: 'तपाईंलाई किन गिरफ्तार गरिएको छ भन्ने कुरा थाहा पाउने अधिकार छ।',
