    pa: 'ਮੀਰਾਂਡਾ ਹੱਕਾਂ ਨੂੰ ਕਸਟੋਡੀਅਲ ਇੰਟਰਰੋਗੇਸ਼ਨ ਤੋਂ ਪਹਿਲਾਂ ਪੜ੍ਹਨਾ ਚਾਹੀਦਾ ਹੈ।',
