    ms: 'Hak Miranda mesti dibaca sebelum soal siasat dalam tahanan.',
    ne: 'मिराण्डा अधिकारहरू हिरासतमा सोधपुछ गर्नु अघि पढ्नुपर्छ।',
    so: 'Xuquuqda Miranda waa in la akhriyaa ka hor intaan la weydiin xabsi.',
