    pa: 'ਤੁਹਾਨੂੰ ਗ੍ਰਿਫਤਾਰੀ ਤੋਂ 48 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਇੱਕ ਜੱਜ ਦੇ ਸਾਹਮਣੇ ਲਿਆਉਣਾ ਚਾਹੀਦਾ ਹੈ।',
