    pt: 'Você não precisa abrir a porta para o ICE sem um mandado judicial assinado.',
    ru: 'Вы не обязаны открывать дверь для ICE без подписанного судебного ордера.',
    ja: '署名された司法令状がない限り、ICEにドアを開ける必要はありません。',
    am: 'የተፈረደ የፍርድ ቃል ያለው ወደ ICE ድርድር አይኖርም።',
    te: 'సంతకం చేసిన న్యాయ ఉత్తర్వు లేకుండా ICE కు తలుపు తెరవాల్సిన అవసరం లేదు.',
    pa: 'ਤੁਹਾਨੂੰ ਦਸਤਖਤ ਕੀਤੇ ਗਏ ਨਿਆਂਕਾਰੀ ਵਾਰੰਟ ਦੇ ਬਿਨਾਂ ICE ਲਈ ਦਰਵਾਜਾ ਖੋਲ੍ਹਣ ਦੀ ਲੋੜ ਨਹੀਂ ਹੈ।',
    ta: 'கையெழுத்திடப்பட்ட நீதிமன்ற உத்தி இல்லாமல் ICEக்கு கதவை திறக்க வேண்டிய அவசியமில்லை.',
    bn: 'সাক্ষরিত বিচারিক ওয়ারেন্ট ছাড়া আপনাকে ICE এর জন্য দরজা খুলতে হবে না।',
    id: 'Anda tidak perlu membuka pintu untuk ICE tanpa surat perintah pengadilan yang ditandatangani.',
    ur: 'آپ کو بغیر دستخط شدہ عدالتی وارنٹ کے ICE کے لیے دروازہ نہیں کھولنا ہے۔',
    tr: 'İmzalı bir mahkeme kararı olmadan ICE\'a kapıyı açmak zorunda değilsiniz.',
    sw: 'Huna haja ya kufungua mlango kwa ICE bila hati ya mahakama iliyosainiwa.',
    it: 'Non devi aprire la porta all\'ICE senza un mandato giudiziario firmato.',
    th: 'คุณไม่จำเป็นต้องเปิดประตูให้ ICE โดยไม่มีหมายศาลที่ลงนาม',
    ms: 'Anda tidak perlu membuka pintu kepada ICE tanpa waran mahkamah yang ditandatangani.',
    ne: 'तपाईंलाई हस्ताक्षर गरिएको न्यायिक वारंट बिना ICE का लागि ढोका खोल्न आवश्यक छैन।',
    so: 'Ma ahan inaad albaabka u furto ICE adoon haysan amar maxkamadeed oo saxiixan.',
