    ru: 'У вас есть право связаться с вашим консульством, если вас задержали.',
    ja: '拘束された場合、領事館に連絡する権利があります。',
    am: 'በተወሰኑ እንደ ተወሰኑ ወንጌል ይጠይቁ።',
    te: 'మీరు నిర్బంధితమైనట్లయితే మీ కౌన్సులేట్‌ను సంప్రదించడానికి మీకు హక్కు ఉంది.',
    pa: 'ਜੇ ਤੁਸੀਂ ਗਿਰਫਤਾਰ ਹੋ ਜਾਂਦੇ ਹੋ ਤਾਂ ਤੁਹਾਨੂੰ ਆਪਣੇ ਕੌਂਸੁਲੇਟ ਨਾਲ ਸੰਪਰਕ ਕਰਨ ਦਾ ਹੱਕ ਹੈ।',
    ta: 'நீங்கள் கைது செய்யப்பட்டால் உங்கள் தூதரகத்தை தொடர்பு கொள்ள உரிமை உண்டு.',
    bn: 'আপনার আটক হলে আপনার কনস্যুলেটের সাথে যোগাযোগ করার অধিকার রয়েছে।',
    id: 'Anda berhak menghubungi konsulat Anda jika ditahan.',
    ur: 'اگر آپ کو حراست میں لیا جائے تو آپ کو اپنے قونصل خانے سے رابطہ کرنے کا حق ہے۔',
    tr: 'Söylediğiniz her şey göçmenlik işlemlerinde kullanılabilir.',
    sw: 'Una haki ya kuwasiliana na ubalozi wako ikiwa umekamatwa.',
    it: 'Hai il diritto di contattare il tuo consolato se sei detenuto.',
    th: 'คุณมีสิทธิ์ติดต่อสถานกงสุลของคุณหากถูกควบคุมตัว.',
    ms: 'Anda berhak menghubungi konsulat anda jika ditahan.',
    ne: 'यदि तपाईंलाई थुनामा राखिएको छ भने तपाईंको कन्सुलेटसँग सम्पर्क गर्ने अधिकार छ।',
    so: 'Waxaad xaq u leedahay inaad la xiriirto qunsulkaaga haddii la xiro.',
