    fr: 'Tout ce que vous dites peut être utilisé dans des procédures d\'immigration.',
    pt: 'Qualquer coisa que você diga pode ser usada em processos de imigração.',
    ru: 'Все, что вы скажете, может быть использовано в иммиграционных процедурах.',
    ja: 'あなたが言うことはすべて、移民手続きに使用される可能性があります。',
    am: 'የምንም ነገር ይቀበሉ ይችላሉ ወይም ይህን ይቀበሉ ይችላሉ።',
    te: 'మీరు చెప్పే ఏదైనా ఇమ్మిగ్రేషన్ ప్రక్రియల్లో ఉపయోగించబడవచ్చు.',
    pa: 'ਤੁਸੀਂ ਜੋ ਕੁਝ ਵੀ ਕਹਿੰਦੇ ਹੋ ਉਹ ਇਮੀਗ੍ਰੇਸ਼ਨ ਕਾਰਵਾਈਆਂ ਵਿੱਚ ਵਰਤਿਆ ਜਾ ਸਕਦਾ ਹੈ।',
    ta: 'நீங்கள் கூறும் எந்தவொரு விஷயமும் குடியிருப்புச் செயல்முறைகளில் பயன்படுத்தப்படலாம்.',
    bn: 'আপনি যা কিছু বলেন তা অভিবাসন প্রক্রিয়ায় ব্যবহার করা যেতে পারে।',
    id: 'Apa pun yang Anda katakan dapat digunakan dalam proses imigrasi.',
    ur: 'آپ جو کچھ بھی کہتے ہیں اسے امیگریشن کی کارروائیوں میں استعمال کیا جا سکتا ہے۔',
    sw: 'Kila kitu unachosema kinaweza kutumika katika taratibu za uhamiaji.',
    it: 'Qualsiasi cosa tu dica può essere utilizzata nelle procedure di immigrazione.',
    th: 'สิ่งที่คุณพูดสามารถนำไปใช้ในกระบวนการตรวจคนเข้าเมืองได้.',
    ms: 'Apa sahaja yang anda katakan boleh digunakan dalam proses imigresen.',
    ne: 'तपाईंले भनेको कुनै पनि कुरा आप्रवासन प्रक्रियामा प्रयोग गर्न सकिन्छ।',
    so: 'Wax kasta oo aad tidhaahdo waxaa loo isticmaali karaa habraacyada socdaalka.',
    ht: 'Nenpòt bagay ou di ka itilize nan pwosedi imigrasyon.',
    tr: 'Söylediğiniz her şey göçmenlik işlemlerinde kullanılabilir.',
