    am: 'እባኮትን በተወሰኑ እንደ ምን ይህ ነው ይቀጥሉ።',
    te: 'మీరు నిర్బంధిత అయితే వెంటనే ఒక వలస న్యాయవాదిని సంప్రదించండి.',
    pa: 'ਜੇ ਤੁਸੀਂ ਗ੍ਰਿਫਤਾਰ ਹੋਏ ਹੋ ਤਾਂ ਤੁਰੰਤ ਇੱਕ ਇਮੀਗ੍ਰੇਸ਼ਨ ਵਕੀਲ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।',
