    bn: 'যদি আটক করা হয় তবে অবিলম্বে একজন অভিবাসন আইনজীবীর সাথে যোগাযোগ করুন।',
    id: 'Segera hubungi pengacara imigrasi jika Anda ditahan.',
    ur: 'اگر آپ کو حراست میں لیا جائے تو فوری طور پر ایک امیگریشن وکیل سے رابطہ کریں۔',
    tr: 'Gözaltına alındıysanız hemen bir göçmen avukatıyla iletişime geçin.',
    sw: 'Wasiliana na wakili wa uhamiaji mara moja ikiwa umekamatwa.',
    it: 'Contatta immediatamente un avvocato per l\'immigrazione se sei detenuto.',
    th: 'ติดต่อทนายความด้านการเข้าเมืองทันทีหากถูกควบคุมตัว',
