    ne: 'यदि तपाईंलाई पक्राउ गरिएको छ भने तुरुन्तै एक आप्रवासी वकिलसँग सम्पर्क गर्नुहोस्।',
    so: 'La xiriir qareen socdaal si degdeg ah haddii lagaa qabto.',
