    pa: 'ਤੁਸੀਂ ਖਿੜਕੀ ਜਾਂ ਦਰਵਾਜੇ ਰਾਹੀਂ ਵਾਰੰਟ ਦੇਖਣ ਲਈ ਪੁੱਛ ਸਕਦੇ ਹੋ।',
