    tr: 'Pencereden veya kapıdan arama emrini görmeyi isteyebilirsiniz.',
    sw: 'Unaweza kuuliza kuona hati hiyo kupitia dirisha au mlango.',
    it: 'Puoi chiedere di vedere il mandato attraverso una finestra o una porta.',
    th: 'คุณสามารถขอให้ดูหมายค้นผ่านหน้าต่างหรือประตู',
    ms: 'Anda boleh meminta untuk melihat waran melalui tingkap atau pintu.',
    ne: 'तपाईंले झ्याल वा ढोकाबाट वारंट देख्नका लागि सोध्न सक्नुहुन्छ।',
    so: 'Waxaad weydiin kartaa inaad aragto amarka adigoo ka soo dhex eegaya daaqadda ama albaabka.',
    ht: 'Ou ka mande pou wè manda a atravè yon fenèt oswa pòt.',
