    am: '"እንደ ተመለከተ እና እንደ ተነገረ" በመግባት በፊት በአጠቃላይ ይጠይቃል።',
    te: '"తట్టండి మరియు ప్రకటించండి" సాధారణంగా ప్రవేశానికి ముందు అవసరం.',
    pa: '"ਨੱਕ ਅਤੇ ਐਲਾਨ" ਆਮ ਤੌਰ \'ਤੇ ਦਾਖਲ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਲੋੜੀਂਦਾ ਹੈ।',
    ta: '"தட்டவும் மற்றும் அறிவிக்கவும்" என்பது பொதுவாக நுழைவுக்கு முன்பு தேவைப்படுகிறது.',
    bn: '"নক এবং ঘোষণা" সাধারণত প্রবেশের আগে প্রয়োজন।',
    id: '"ketuk dan umumkan" biasanya diperlukan sebelum masuk.',
