    tr: '"kapı çal ve duyur" genellikle girmeden önce gereklidir.',
    sw: '"gonga na tangaza" kwa kawaida inahitajika kabla ya kuingia.',
    it: 'Un "bussare e annunciare" è solitamente richiesto prima dell\'ingresso.',
    th: '"เคาะและประกาศ" มักจะต้องการก่อนเข้าประตู.',
