    ta: 'நீங்கள் கதவை திறந்தால், வெளியே சென்று உங்கள் பின்னால் கதவை மூடுங்கள்.',
    bn: 'যদি আপনি দরজা খুলেন, তবে বাইরে যান এবং আপনার পিছনে দরজা বন্ধ করুন।',
