  'rights.q1_exp': {
    en: 'Drivers must provide their license, vehicle registration, and proof of insurance when lawfully stopped.',
    es: 'Los conductores deben proporcionar su licencia, registro del vehículo y prueba de seguro cuando sean detenidos legalmente.',
    'zh-CN': '司机在合法被拦下时必须提供他们的驾照、车辆登记和保险证明。',
    'zh-TW': '駕駛者在合法被攔下時必須提供他們的駕駛執照、車輛登記和保險證明。',
    vi: 'Người lái xe phải cung cấp giấy phép, đăng ký xe và chứng minh bảo hiểm khi bị dừng hợp pháp.',
    tl: 'Dapat magbigay ng lisensya, rehistro ng sasakyan, at patunay ng seguro ang mga drayber kapag sila ay nahuli nang ayon sa batas.',
    hi: 'ड्राइवरों को कानूनन रोके जाने पर अपनी लाइसेंस, वाहन पंजीकरण और बीमा का प्रमाण प्रदान करना चाहिए।',
    ko: '운전자는 법적으로 정지되었을 때 면허증, 차량 등록증 및 보험 증명을 제공해야 합니다.',
    ar: 'يجب على السائقين تقديم رخصتهم، وتسجيل المركبة، وإثبات التأمين عند التوقف عن القانون.',
    fr: 'Les conducteurs doivent fournir leur permis, l\'immatriculation du véhicule et une preuve d\'assurance lorsqu\'ils sont légalement arrêtés.',
    pt: 'Os motoristas devem fornecer sua licença, registro do veículo e comprovante de seguro quando parados legalmente.',
    ru: 'Водители должны предоставить свои права, регистрацию транспортного средства и доказательство страховки при законной остановке.',
    ja: '運転者は、合法的に停止されたときに運転免許証、車両登録、および保険証明を提供しなければなりません。',
    am: 'አውቶቡስ በሕገ-ወጥ ተወዳድር ላይ ሲወድቅ የአውቶቡስ የምርጫ መዝገብ እና የእርስዎን የተመረጡ የእንደዚህ የምርጫ መዝገብ ይሰጣሉ።',
    te: 'చాలా చట్టబద్ధంగా ఆపబడినప్పుడు డ్రైవర్లు వారి లైసెన్స్, వాహన నమోదు మరియు బీమా సాక్ష్యం అందించాలి.',
    pa: 'ਡਰਾਈਵਰਾਂ ਨੂੰ ਕਾਨੂੰਨੀ ਰੂਪ ਵਿੱਚ ਰੋਕਿਆ ਜਾਣ \'ਤੇ ਆਪਣੀ ਲਾਇਸੈਂਸ, ਵਾਹਨ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਅਤੇ ਬੀਮਾ ਦਾ ਸਬੂਤ ਪ੍ਰਦਾਨ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ।',
    ta: 'சட்டப்படி நிறுத்தப்படும் போது ஓட்டுநர்கள் தங்கள் உரிமம், வாகன பதிவு மற்றும் காப்பீட்டு சான்று வழங்க வேண்டும்.',
    bn: 'চালকদের আইনত আটক করার সময় তাদের লাইসেন্স, যানবাহন নিবন্ধন এবং বীমার প্রমাণ দিতে হবে।',
    id: 'Pengemudi harus memberikan lisensi, registrasi kendaraan, dan bukti asuransi saat dihentikan secara sah.',
    ur: 'ڈرائیوروں کو قانونی طور پر روکے جانے پر اپنی لائسنس، گاڑی کی رجسٹریشن، اور انشورنس کا ثبوت فراہم کرنا ہوگا۔',
    tr: 'Sürücüler, yasal olarak durdurulduklarında lisanslarını, araç kaydını ve sigorta belgesini sağlamalıdır.',
    sw: 'Madereva lazima watoe leseni zao, usajili wa gari, na uthibitisho wa bima wanapositishwa kisheria.',
    it: 'Gli autisti devono fornire la propria patente, registrazione del veicolo e prova di assicurazione quando vengono fermati legalmente.',
    th: 'ผู้ขับขี่ต้องแสดงใบอนุญาตทะเบียนรถและหลักฐานการประกันภัยเมื่อถูกหยุดตามกฎหมาย',
    ms: 'Pemandu mesti memberikan lesen, pendaftaran kenderaan, dan bukti insurans apabila dihentikan secara sah.',
    ne: 'चालकहरूले कानूनी रूपमा रोकेका बेला आफ्नो लाइसेन्स, सवारी साधनको दर्ता र बीमा प्रमाण प्रदान गर्नुपर्छ।',
    so: 'Darawallada waa inay bixiyaan liisankooda, diiwaangelinta gaadiidka, iyo caddeynta caymiska marka si sharci ah loo joojiyo.',
    ht: 'Chofè yo dwe bay lisans yo, enskripsyon machin nan, ak prèv asirans lè yo sispann legalman.',
  },
