  'rights.q2_exp': {
    en: 'Since 2013 (Salinas v. Texas), you must explicitly state you are invoking your right to silence — staying quiet alone may not protect you.',
    es: 'Desde 2013 (Salinas v. Texas), debe declarar explícitamente que está invocando su derecho al silencio; quedarse callado solo puede no protegerlo.',
    'zh-CN': '自2013年（Salinas诉德克萨斯州）以来，您必须明确表示您行使保持沉默的权利——仅仅保持沉默可能无法保护您。',
    'zh-TW': '自2013年（Salinas訴德克薩斯州）以來，您必須明確表示您行使保持沉默的權利——僅僅保持沉默可能無法保護您。',
    vi: 'Kể từ năm 2013 (Salinas kiện Texas), bạn phải tuyên bố rõ ràng rằng bạn đang viện dẫn quyền im lặng của mình - chỉ im lặng có thể không bảo vệ bạn.',
    tl: 'Mula noong 2013 (Salinas v. Texas), kailangan mong tahasang ipahayag na ikaw ay nagsusumamo ng iyong karapatan na manahimik - ang manahimik lamang ay maaaring hindi protektahan ka.',
    hi: '2013 (सलिनास बनाम टेक्सास) से, आपको स्पष्ट रूप से बताना होगा कि आप अपने चुप रहने के अधिकार का उपयोग कर रहे हैं - केवल चुप रहना आपको सुरक्षित नहीं कर सकता।',
    ko: '2013년 (Salinas 대 텍사스) 이후로, 당신은 침묵할 권리를 주장한다고 명시적으로 말해야 합니다 - 단순히 조용히 있는 것만으로는 당신을 보호하지 못할 수 있습니다.',
    ar: 'منذ عام 2013 (ساليناس ضد تكساس)، يجب عليك أن تصرح بوضوح أنك تستند إلى حقك في الصمت - البقاء صامتًا وحده قد لا يحميك.',
    fr: 'Depuis 2013 (Salinas c. Texas), vous devez déclarer explicitement que vous invoquez votre droit au silence - rester silencieux seul peut ne pas vous protéger.',
    pt: 'Desde 2013 (Salinas v. Texas), você deve declarar explicitamente que está invocando seu direito ao silêncio - ficar em silêncio sozinho pode não protegê-lo.',
    ru: 'С 2013 года (Salinas против Техаса) вы должны явно заявить, что призываете к своему праву на молчание — просто молчание может вас не защитить.',
    ja: '2013年（サリナス対テキサス）以来、沈黙する権利を行使していることを明示的に述べる必要があります — ただ黙っているだけではあなたを守れないかもしれません。',
    am: 'ከ2013 ጀምሮ (ሳሊናስ በቴክስ ውስጥ) የምስጢር መብትዎን እንደ እውነት መግለጽ አለብዎት - ብቻ ዝም ብለው መቆም እንደሚያስቀምጥዎት ይችላል።',
    te: '2013 నుండి (సాలినాస్ వర్సెస్ టెక్సాస్), మీరు మీ నిశ్శబ్దంగా ఉండే హక్కును వినియోగిస్తున్నారని స్పష్టంగా చెప్పాలి - కేవలం నిశ్శబ్దంగా ఉండడం మీను రక్షించకపోవచ్చు.',
    pa: '2013 ਤੋਂ (ਸਾਲਿਨਾਸ ਵਿਰੁੱਧ ਟੈਕਸਸ), ਤੁਹਾਨੂੰ ਸਪਸ਼ਟ ਤੌਰ \'ਤੇ ਕਹਿਣਾ ਪੈਣਾ ਹੈ ਕਿ ਤੁਸੀਂ ਆਪਣੇ ਚੁੱਪ ਰਹਿਣ ਦੇ ਹੱਕ ਦਾ ਹਵਾਲਾ ਦੇ ਰਹੇ ਹੋ - ਸਿਰਫ ਚੁੱਪ ਰਹਿਣਾ ਤੁਹਾਨੂੰ ਬਚਾਉਣ ਵਿੱਚ ਸਹਾਇਕ ਨਹੀਂ ਹੋ ਸਕਦਾ।',
    ta: '2013 முதல் (சாலினாஸ் வி. டெக்சாஸ்), நீங்கள் உங்கள் அமைதியாக இருக்க உரிமையை invoke செய்கிறேன் என்று தெளிவாக கூற வேண்டும் - அமைதியாக இருப்பது மட்டுமே உங்களை பாதுகாக்காது.',
    bn: '২০১৩ সাল থেকে (সালিনাস বনাম টেক্সাস), আপনাকে স্পষ্টভাবে বলতে হবে যে আপনি আপনার চুপ থাকার অধিকার ব্যবহার করছেন - শুধু চুপ থাকা আপনাকে রক্ষা নাও করতে পারে।',
    id: 'Sejak 2013 (Salinas v. Texas), Anda harus secara eksplisit menyatakan bahwa Anda menggunakan hak untuk diam - hanya tetap diam mungkin tidak melindungi Anda.',
    ur: '2013 (سالیناس بمقابلہ ٹیکساس) سے، آپ کو واضح طور پر بیان کرنا ہوگا کہ آپ خاموش رہنے کے اپنے حق کا دعویٰ کر رہے ہیں - صرف خاموش رہنا آپ کی حفاظت نہیں کر سکتا۔',
    tr: '2013\'ten beri (Salinas v. Texas), sessiz kalma hakkınızı kullandığınızı açıkça belirtmelisiniz - sadece sessiz kalmak sizi korumayabilir.',
    sw: 'Tangu mwaka wa 2013 (Salinas v. Texas), lazima ueleze wazi kwamba unatumia haki yako ya kukaa kimya - kukaa kimya pekee hakukulinda.',
    it: 'Dal 2013 (Salinas contro Texas), devi dichiarare esplicitamente di invocare il tuo diritto al silenzio - rimanere in silenzio da solo potrebbe non proteggerti.',
    th: 'ตั้งแต่ปี 2013 (Salinas v. Texas) คุณต้องระบุอย่างชัดเจนว่าคุณกำลังใช้สิทธิ์ในการรักษาความเงียบ - การเงียบเพียงอย่างเดียวอาจไม่ปกป้องคุณ',
    ms: 'Sejak 2013 (Salinas lwn Texas), anda mesti menyatakan dengan jelas bahawa anda menggunakan hak untuk berdiam diri - hanya berdiam diri mungkin tidak melindungi anda.',
    ne: '२०१३ देखि (सालिनास बनाम टेक्सास), तपाईंले स्पष्ट रूपमा भन्नु पर्छ कि तपाईं चुप रहने अधिकारको प्रयोग गर्दै हुनुहुन्छ - केवल चुप रहनु तपाईंलाई सुरक्षा दिन सक्दैन।',
    so: 'Tan iyo 2013 (Salinas v. Texas), waa inaad si cad u sheegtaa inaad ku andacoonayso xaqaaga aamusan - kaliya aamusan ma ilaalin karto.',
    ht: 'Depi 2013 (Salinas v. Texas), ou dwe deklare klèman ou ap fè apèl a dwa ou pou rete silans - rete silans pou kont li ka pa pwoteje ou.',
  },
