    te: 'మీరు ప్రజల్లో పోలీసులను చట్టపరంగా రికార్డు చేయగలరా?',
    pa: 'ਕੀ ਤੁਸੀਂ ਜਨਤਕ ਤੌਰ \'ਤੇ ਪੁਲਿਸ ਨੂੰ ਕਾਨੂੰਨੀ ਤੌਰ \'ਤੇ ਰਿਕਾਰਡ ਕਰ ਸਕਦੇ ਹੋ?',
