    tr: 'Evet, kendilerini memur olarak tanıtırlarsa',
    sw: 'Ndio, ikiwa wanajitambulisha kama maafisa',
    it: 'Sì, se si identificano come ufficiali',
    th: 'ใช่ หากพวกเขาระบุว่าตนเป็นเจ้าหน้าที่',
    ms: 'Ya, jika mereka mengenal pasti diri mereka sebagai pegawai',
    ne: 'हो, यदि उनीहरूले आफूलाई अधिकारीको रूपमा पहिचान गर्छन्',
    so: 'Haa, haddii ay isku aqoonsadaan sidii saraakiil',
    ht: 'Wi, si yo idantifye tèt yo kòm ofisye',
